const badge=(s)=>`<span class="badge ${({Confirmado:'',Pendente:'orange',Concluído:'blue',Cancelado:'rose',Ativo:'',Inativo:'gray',Pago:'',Recebido:'',Agendado:'blue','Em andamento':'orange',Emitido:'',Rascunho:'gray',Vencido:'rose'})[s]||''}">${esc(s)}</span>`;
