function emptyDatabase(){return {version:3,patients:[],appointments:[],transactions:[],documents:[],simulations:[],sessions:[],activity:[],settings:{clinic:'Minha clínica',doctor:'Profissional',specialty:'',phone:'',email:'',address:'',reminders:false,notifications:true}}}
let db=emptyDatabase();
let route='inicio',selectedPatient='p1',patientTab='visao',selectedDate=dateKey(),patientQuery='',patientStatus='Todos',patientView='grid',agendaStatus='Todos',financeFilter='Todos',documentPatient='p1',documentType='Declaração de comparecimento',callState=null,callTimer=null,smile={procedure:'clareamento',mode:'photo',patient:'p5',shade:'BL1',alignment:65,shape:50,compare:50,photo:null,generated:false},chartPeriod='Semana',tourStep=-1;
async function save(){return window.EvolunaCloud.save(db)}
async function activity(text,ico='check'){db.activity.unshift({text,date:dateKey(),icon:ico});db.activity=db.activity.slice(0,20);return save()}
function patient(id){return db.patients.find(p=>p.id===id)||db.patients[0]}
function toast(text){const el=$('#toast');el.innerHTML=icon('check',15)+`<span>${esc(text)}</span>`;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3600)}
const navItems=[['inicio','home','Visão geral'],['agenda','calendar','Agenda'],['pacientes','users','Pacientes'],['prontuarios','record','Prontuários'],['sorriso','sparkles','Sorriso IA','DEMO'],['teleconsultas','video','Teleconsultas'],['documentos','file','Documentos'],['simulacao-financiamento','money','Simulação de financiamento'],['financeiro','wallet','Financeiro'],['relatorios','chart','Relatórios'],['configuracoes','settings','Configurações'],['mais','settings','Mais']];
function renderNav(){const active=['paciente','prontuario','prontuarios'].includes(route)?'pacientes':['financeiro','relatorios','configuracoes'].includes(route)?'mais':route;$('#navigation').innerHTML=navItems.filter(([r])=>!['sorriso','teleconsultas','prontuarios','financeiro','relatorios','configuracoes'].includes(r)).map(([r,i,t,tag])=>r==='simulacao-financiamento'?`<button class="nav-item nav-placeholder" type="button" disabled title="Em breve" aria-label="Simulação de financiamento — em breve">${icon(i)}<span>${t}</span></button>`:`<a href="#${r}" class="nav-item ${active===r?'active':''}" ${active===r?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${tag?`<span class="nav-tag">${tag}</span>`:''}</a>`).join('');$('#breadcrumb-title').setAttribute('href',route==='prontuario'?location.hash:'#'+route);$('#breadcrumb-title').textContent=route==='paciente'?'Perfil do paciente':route==='prontuario'?'Prontuário':route==='prontuarios'?'Pacientes':navItems.find(n=>n[0]===route)?.[2]||'Visão geral';$('#search-icon').innerHTML=icon('heart',18);$('#bell-icon').innerHTML=icon('bell',18);$('.header-patient-search-icon').innerHTML=icon('search',16);$('.clinic>span:nth-child(2)').innerHTML='Sorriso IA<small>Planejamento de sorrisos</small>';$('.clinic').classList.toggle('active',route==='sorriso');$('.teleconsulta-shortcut .clinic-icon').innerHTML=icon('video',18);$('.teleconsulta-shortcut').classList.toggle('active',route==='teleconsultas');$('.profile>span:nth-child(2)').innerHTML=`${esc(db.settings.doctor)}<small>Conta particular</small>`}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div><div class="heading-actions">${actions}</div></div>`}
function card(title,subtitle,body,action='',cls=''){return `<section class="card ${cls}"><div class="card-header"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>${body}</section>`}
function kpi(label,value,ico,bottom,change=''){return `<div class="kpi"><div class="kpi-top"><span>${label}</span><span class="kpi-icon">${icon(ico,16)}</span></div><div class="kpi-value">${value}</div><div class="kpi-bottom">${change?`<span class="growth">${change}</span>`:''}${bottom}</div></div>`}
function todayAppointments(){return db.appointments.filter(a=>a.date===dateKey()&&a.status!=='Cancelado').sort((a,b)=>a.time.localeCompare(b.time))}
function patientRow(p,compact=false){return `<tr><td><button class="person-cell row-action" data-action="patient" data-id="${p.id}">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${esc(p.email)}</small></span></button></td>${compact?'':`<td>${esc(p.phone)}</td>`}<td>${esc(p.procedure||'Avaliação inicial')}</td><td>${badge(p.status)}</td><td><button class="row-action" data-action="patient" data-id="${p.id}" aria-label="Abrir ${esc(p.name)}">${icon('arrow',14)}</button></td></tr>`}
function activityChart(){const week=chartPeriod==='Semana';const values=week?[7,10,8,12,9,5,2]:[32,46,39,53,48,41];const labels=week?['Seg','Ter','Qua','Qui','Sex','Sáb','Dom']:['Mai','Jun','Jul','Ago','Set','Out'];return `<div class="chart-legend"><span><i></i> Consultas</span><span><i></i> Retornos</span><span style="margin-left:auto;color:#aab39d">Histórico ilustrativo</span></div><div class="bar-chart"><span class="chart-y top">${week?15:60}</span><span class="chart-y middle">${week?8:30}</span><span class="chart-y bottom">0</span>${values.map((v,i)=>`<div class="bar-pair"><div class="bar" style="height:${v/(week?15:60)*100}%" title="${v} consultas ilustrativas"></div><div class="bar light" style="height:${v/(week?15:60)*58}%"></div><span class="bar-label">${labels[i]}</span></div>`).join('')}</div><div class="chart-summary"><span>Uma visão do ritmo da sua clínica</span><strong>↑ 12,8% <span class="muted">no cenário de exemplo</span></strong></div>`}
function toothArt(){return `<svg viewBox="0 0 230 190" fill="none"><ellipse cx="125" cy="159" rx="69" ry="13" fill="#102e2566"/><path d="M83 34c18-14 29 4 42 1 17-5 33-9 42 4 15 21-3 58-9 77-7 22-12 36-22 33-10-3-7-42-16-42-10 0-8 42-19 42-10 0-14-18-21-38-8-25-20-58 3-77Z" fill="#e9eedb"/><path d="M100 39c14 6 18 4 28 1" stroke="#b8ca9e" stroke-width="4" stroke-linecap="round"/><path d="M90 50c-8 10-1 30 3 39" stroke="white" stroke-width="5" stroke-linecap="round" opacity=".8"/><path d="m185 44 4 10 11 4-11 4-4 11-4-11-11-4 11-4Zm-126 63 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z" fill="#c3d695"/><circle cx="57" cy="48" r="3" fill="#87a274"/><circle cx="178" cy="136" r="4" fill="#87a274"/></svg>`}
function renderHome(){const appointments=todayAppointments();const upcoming=appointments.slice(0,4);const hour=new Date().getHours();const greeting=hour<12?'Bom dia':hour<18?'Boa tarde':'Boa noite';return `<div class="overview-page">`+heading(`${greeting}, ${esc(db.settings.doctor)} <span style="color:#b1bd96;font-weight:400">✺</span>`,'Um novo dia para transformar sorrisos. Vamos começar?',`<span class="date-chip">${icon('calendar',13)}${prettyDate(dateKey(),{day:'numeric',month:'long',year:'numeric'})}</span>${btn('Novo agendamento','new-appointment','plus','primary')}`)+`<section class="hero-banner with-smile-photo"><div class="hero-text"><div class="eyebrow">${icon('sparkles',12)} TECNOLOGIA A SERVIÇO DO CUIDADO</div><h2>O próximo sorriso começa<br>com um <em>novo olhar.</em></h2><p>Explore possibilidades estéticas e encante seus pacientes.</p><button class="button lime" data-route="sorriso">Explorar Sorriso IA ${icon('arrow',13)}</button></div><figure class="hero-smile-photo hero-dental-care"><svg viewBox="1128 28 888 655" preserveAspectRatio="xMidYMid slice" role="img" aria-label="Imagem ilustrativa de atendimento odontológico com paciente, luvas e espelho dental"><image href="/assets/banner-opcao-2.png" width="2098" height="749"/></svg><figcaption>Imagem adaptada com IA</figcaption></figure></section><div class="kpi-grid home-kpis">${kpi('Pacientes cadastrados',db.patients.length.toString().padStart(2,'0'),'users','na sua clínica',`${db.patients.filter(p=>p.status==='Ativo').length} ativos`)}${kpi('Consultas hoje',appointments.length.toString().padStart(2,'0'),'calendar',`${appointments.filter(a=>a.status==='Confirmado').length} confirmadas`)}${kpi('Sorrisos planejados',db.simulations.length.toString().padStart(2,'0'),'sparkles','simulações salvas no navegador')}</div>${window.HomeAnalytics.render()}<div class="overview-section-heading"><div><span>ACOMPANHAMENTO DO DIA</span><h2>Sua rotina, em foco.</h2></div><p>Agenda e cuidado conectados.</p></div><div class="dashboard-grid home-agenda">${card('Agenda de hoje',`${appointments.length} atendimentos no seu dia`,`<div class="card-body">${upcoming.map(a=>{const p=patient(a.patient);return `<div class="appointment-row"><span class="appointment-time">${a.time}</span>${avatar(p)}<div class="appointment-info"><strong>${esc(p.name)}</strong><small>${esc(a.procedure)}</small></div>${badge(a.status)}</div>`}).join('')||empty('Agenda livre','Adicione o primeiro atendimento de hoje.')}</div>`,`<button class="card-link" data-route="agenda">Ver agenda ${icon('arrow',12)}</button>`)}<section class="tele-hero"><img class="tele-hero-photo" src="/assets/teleconsulta.webp" alt="Foto ilustrativa de uma profissional em uma consulta por vídeo"><div class="tele-hero-overlay"></div><div class="tele-hero-content"><div class="eyebrow">${icon('video',13)} CUIDADO ALÉM DO CONSULTÓRIO</div><h3>Seu cuidado continua.<br>Mesmo à distância.</h3><p>Converse com seu paciente por vídeo para esclarecer dúvidas, orientar cuidados e acompanhar a evolução do tratamento entre as consultas presenciais.</p><ul class="tele-benefits"><li><strong>Encontro simples:</strong> envie o link da chamada; o paciente entra pelo navegador, sem cadastro.</li><li><strong>Paciente em contexto:</strong> consulte histórico, plano de tratamento e documentos durante a conversa.</li><li><strong>Continuidade do cuidado:</strong> registre orientações e gere os documentos necessários na própria sessão.</li></ul><button class="button lime" data-route="teleconsultas">Abrir teleconsulta ${icon('arrow',13)}</button><span class="tele-photo-label">Imagem ilustrativa</span></div></section></div><div class="lower-grid home-patients">${card('Seus pacientes','Cuidado contínuo, relações que importam',`<div class="table-wrap"><table><thead><tr><th>Paciente</th><th>Último procedimento</th><th>Status</th><th></th></tr></thead><tbody>${db.patients.slice(0,3).map(p=>patientRow(p,true)).join('')}</tbody></table></div>`,`<button class="card-link" data-route="pacientes">Ver todos ${icon('arrow',12)}</button>`)}</div></div>`}
function patientCards(){const list=db.patients.filter(p=>(patientStatus==='Todos'||p.status===patientStatus)&&`${p.name} ${p.email} ${p.phone} ${p.cpf||''}`.toLowerCase().includes(patientQuery.toLowerCase()));if(!list.length)return empty('Nenhum paciente encontrado','Tente outro nome ou ajuste o filtro.');return patientView==='grid'?`<div class="patient-grid">${list.map(p=>`<article class="patient-card"><div class="patient-card-top"><button type="button" class="profile-photo-button patient-card-photo" data-action="patient-photo" data-id="${p.id}" aria-label="${p.photo?'Trocar':'Adicionar'} foto de ${esc(p.name)}" title="${p.photo?'Trocar foto':'Adicionar foto'}">${avatar(p)}<span class="photo-camera">${icon('upload',12)}</span></button>${badge(p.status)}</div><h3>${esc(p.name)}</h3><span class="muted" style="font-size:10px">${esc(p.procedure)}</span><div class="patient-contact">${icon('phone',13)}${esc(p.phone)}</div><div class="patient-contact">${icon('mail',13)}${esc(p.email)}</div><div class="patient-card-footer"><span>Última visita: ${prettyDate(p.last)}</span><button class="card-link" data-action="patient" data-id="${p.id}">Ver perfil ${icon('arrow',12)}</button></div></article>`).join('')}</div>`:`<div class="card table-wrap"><table><thead><tr><th>Paciente</th><th>Telefone</th><th>Procedimento</th><th>Status</th><th></th></tr></thead><tbody>${list.map(p=>patientRow(p)).join('')}</tbody></table></div>`}
function renderPatients(){return heading('Pacientes','Cada sorriso tem uma história. Conheça quem confia em você.',btn('Novo paciente','new-patient','plus','primary'))+`<div class="section-toolbar"><div class="input-search">${icon('search',15)}<input id="patient-search" placeholder="Buscar por nome, telefone ou e-mail" value="${esc(patientQuery)}" aria-label="Buscar paciente"></div><div class="filters"><select id="patient-status" aria-label="Filtrar status"><option ${patientStatus==='Todos'?'selected':''}>Todos</option><option ${patientStatus==='Ativo'?'selected':''}>Ativo</option><option ${patientStatus==='Inativo'?'selected':''}>Inativo</option></select><div class="segmented"><button data-action="patient-view" data-value="grid" aria-label="Exibir cartões" class="${patientView==='grid'?'active':''}">${icon('grid',14)}</button><button data-action="patient-view" data-value="list" aria-label="Exibir lista" class="${patientView==='list'?'active':''}">${icon('list',14)}</button></div></div></div><div id="patients-list">${patientCards()}</div><p class="muted" style="font-size:9px;margin-top:20px">${db.patients.length} pacientes cadastrados · Dados salvos na sua conta</p>`}
function renderAgenda(){return window.Agenda.render()}
function renderRecords(){return renderPatients()}
function renderPatient(){if(!db.patients.length)return renderPatients();const p=patient(selectedPatient);const age=Math.max(0,Math.floor((Date.now()-new Date(p.birth+'T12:00'))/31557600000));let body='';if(patientTab==='visao')body=`<div class="two-columns">${card('Informações do paciente','Dados cadastrais do paciente',`<div class="card-body"><div class="detail-grid">${[['CPF',p.cpf||'Não cadastrado'],['Data de nascimento',`${prettyDate(p.birth,{day:'2-digit',month:'2-digit',year:'numeric'})} · ${age} anos`],['Telefone',p.phone],['E-mail',p.email],['Plano',p.plan],['Alergias e atenção',p.allergies],['Status',p.status]].map(([l,v])=>`<div class="detail-field"><small>${l}</small><span>${esc(v)}</span></div>`).join('')}</div><div class="form-section">Observações</div><p style="font-size:11px;color:#8b9a7b">${esc(p.notes||'Nenhuma observação cadastrada.')}</p></div>`)}${card('Próximos atendimentos','Continuidade do cuidado',`<div class="card-body">${db.appointments.filter(a=>a.patient===p.id&&a.date>=dateKey()&&a.status!=='Cancelado').slice(0,4).map(a=>`<div class="appointment-row"><span class="kpi-icon">${icon(a.type==='Teleconsulta'?'video':'calendar',16)}</span><div class="appointment-info"><strong>${esc(a.procedure)}</strong><small>${prettyDate(a.date)} · ${a.time}</small></div>${badge(a.status)}</div>`).join('')||'<p class="muted" style="font-size:11px">Nenhum atendimento agendado.</p>'}${btn('Agendar retorno','new-appointment','plus','',`data-patient="${p.id}"`)}</div>`)}</div>`;if(patientTab==='evolucao')body=card('Linha do tempo','Uma visão da jornada do paciente',`<div class="card-body" style="padding-top:10px">${p.history.map(h=>`<div class="timeline-item"><small>${prettyDate(h.date,{day:'numeric',month:'long',year:'numeric'})}</small><h4>${esc(h.title)}</h4><p>${esc(h.text)}</p></div>`).join('')||empty('A história começa aqui','Adicione uma evolução demonstrativa.')}</div>`,btn('Nova evolução','new-note','plus','primary',`data-id="${p.id}"`));if(patientTab==='odontograma'){const upper=[18,17,16,15,14,13,12,11,21,22,23,24,25,26,27,28],lower=[48,47,46,45,44,43,42,41,31,32,33,34,35,36,37,38];body=card('Odontograma interativo','Clique em um dente para alternar: íntegro → acompanhamento → tratamento.',`<div class="card-body"><div class="chart-legend"><span><i style="background:#dce7d0"></i>Acompanhamento</span><span><i style="background:#e8c89a"></i>Tratamento</span><span>Demonstrativo</span></div><div class="tooth-grid">${[...upper,...lower].map(n=>`<button class="tooth ${p.teeth[n]||''}" data-action="tooth" data-tooth="${n}" aria-label="Dente ${n}: ${p.teeth[n]==='marked'?'acompanhamento':p.teeth[n]==='treatment'?'tratamento':'íntegro'}">${icon('tooth',25)}<span>${n}</span></button>`).join('')}</div><div class="notice" style="margin:0">${icon('info',15)}As marcações são fictícias e ficam salvas apenas neste navegador.</div></div>`)}if(patientTab==='plano')body=card('Plano de tratamento','Procedimentos e valores de exemplo',`<div class="card-body">${p.treatments.map((t,i)=>`<div class="treatment-plan"><div><h4>${esc(t.name)}</h4><small>${esc(t.status)}</small></div><strong>${money(t.value)}</strong></div>`).join('')||'<p class="muted">Nenhum procedimento adicionado.</p>'}<div class="plan-total"><span>Total planejado</span><strong>${money(p.treatments.reduce((s,t)=>s+t.value,0))}</strong></div></div>`,btn('Adicionar procedimento','new-treatment','plus','',`data-id="${p.id}"`));return heading('Perfil do paciente','Uma visão completa de cada história.',`<button class="button ghost" data-route="pacientes">Voltar</button>${btn('Abrir prontuário','open-record','record','primary',`data-id="${p.id}"`)}${btn('Editar paciente','edit-patient','edit','primary',`data-id="${p.id}"`)}`)+`<div class="profile-header"><button class="profile-photo-button" data-action="patient-photo" data-id="${p.id}" aria-label="${p.photo?'Trocar':'Adicionar'} foto de ${esc(p.name)}">${avatar(p)}<span class="photo-camera">${icon('edit',13)}</span></button><div><h2>${esc(p.name)}</h2><button class="photo-inline-button" data-action="patient-photo" data-id="${p.id}">${p.photo?'Trocar foto':'Adicionar foto'}</button><p>${esc(p.procedure)} · ${esc(p.phone)} · ${badge(p.status)}</p></div></div><div class="tabs">${[['visao','Dados cadastrais']].map(([t,l])=>`<button class="tab ${patientTab===t?'active':''}" data-action="patient-tab" data-tab="${t}">${l}</button>`).join('')}</div>${body}`}
const smileProcedures={clareamento:'Clareamento',lentes:'Lentes de contato',facetas:'Facetas'};
function smileProcedure(){return smileProcedures[smile.procedure||'clareamento']||smileProcedures.clareamento}
function smileProcedureOptions(){return `<fieldset class="smile-procedure-options"><legend>Escolha o tratamento</legend><div>${Object.entries(smileProcedures).filter(([id])=>id!=='facetas').map(([id,name])=>`<label class="smile-procedure-option ${(smile.procedure||'clareamento')===id?'selected':''}"><input type="radio" name="smile-procedure" value="${id}" ${(smile.procedure||'clareamento')===id?'checked':''}><span>${name}</span></label>`).join('')}</div></fieldset>`}
const smileShades={BL1:{color:'#fffef9',label:'Branco intenso'},BL2:{color:'#f9f5e9',label:'Branco suave'},A1:{color:'#eee4cf',label:'Natural claro'}};
function smileShade(){return smileShades[smile.shade]?smile.shade:({B1:'BL1',A2:'A1',A3:'A1'}[smile.shade]||'BL1')}
function smileShadeOptions(){return `<fieldset class="smile-shade-field"><legend>Tonalidade do sorriso</legend><div class="smile-shade-grid">${Object.entries(smileShades).map(([shade,details])=>`<button type="button" class="smile-shade-tile ${smileShade()===shade?'selected':''}" data-action="shade" data-value="${shade}" aria-label="Tonalidade ${shade}" aria-pressed="${smileShade()===shade}"><span class="smile-shade-sample" style="background:${details.color}">${smileShade()===shade?icon('check',16):''}</span><strong>${shade}</strong><small>${details.label}</small></button>`).join('')}</div><p class="smile-palette-note">Cores ilustrativas na tela. Não equivalem a uma escala física calibrada.</p></fieldset>`}
function smilePatientResults(query=''){const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const q=norm(query.trim()),digits=q.replace(/\D/g,'');const matches=db.patients.filter(p=>norm(`${p.name} ${p.cpf||''} ${p.phone||''}`).includes(q)||(digits.length>=3&&`${p.cpf||''} ${p.phone||''}`.replace(/\D/g,'').includes(digits)));return matches.map(p=>`<button type="button" class="smile-patient-result" data-action="smile-select-patient" data-id="${esc(p.id)}" aria-label="Selecionar ${esc(p.name)}">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${esc(p.cpf||p.phone||'CPF não informado')}</small></span>${p.id===smile.patient?icon('check',14):''}</button>`).join('')||'<p class="smile-search-empty" role="status">Nenhum paciente encontrado.</p>'}
function smilePlanningPanel(){const p=patient(smile.patient);return `<div class="card-body smile-planning-panel"><label class="field" for="smile-patient-search"><span>Buscar paciente</span><div class="smile-patient-search-box">${icon('search',16)}<input type="search" id="smile-patient-search" placeholder="Nome, CPF ou telefone" autocomplete="off" aria-controls="smile-patient-results" aria-expanded="false"></div></label><div class="smile-patient-search-results" id="smile-patient-results" hidden>${smilePatientResults()}</div><div class="smile-selected-patient">${avatar(p)}<div><small>Paciente selecionado</small><strong>${esc(p.name)}</strong></div></div><div class="smile-selected-treatment"><small>Tratamento selecionado</small><strong>${icon('check',14)}${esc(smileProcedure())}</strong></div>${smileShadeOptions()}<p class="photo-case-note">Prévia ilustrativa para conversar sobre estética. A indicação e o resultado dependem da avaliação odontológica.</p>${btn(smile.photo&&window.Veneer.state().status==='processing'?'Preparando foto…':smile.photo?'Aplicar prévia na foto':'Preparar apresentação','generate-smile','sparkles','primary','style="width:100%" '+(smile.photo&&window.Veneer.state().status==='processing'?'disabled':''))}<div id="simulation-progress"></div></div>`}
function smileProcedurePoints(){const whitening=(smile.procedure||'clareamento')==='clareamento';const points=whitening?[['Formato preservado','Os mesmos dentes, sem mudar o tamanho, o contorno ou os espaços.'],['Posição preservada','O alinhamento e as características individuais permanecem iguais.'],['Clareamento do esmalte','A cor é ajustada nas superfícies dos dentes, preservando sombras e reflexos.'],['Textura e reflexos','Os detalhes visíveis da fotografia são mantidos.'],['Lábios e gengiva','O clareamento fica restrito à região do esmalte.']]:[['Objetivo estético',smileProcedure()+' como tema da conversa sobre o planejamento.'],['Proporções dentárias','Observe a relação entre incisivos centrais, laterais e caninos.'],['Curva do sorriso','Converse sobre contornos e proporções em harmonia com os lábios.'],['Cor e acabamento','Explore uma referência visual de restaurações com textura e translucidez.'],['Planejamento individual','A indicação, o material e o preparo dependem da avaliação odontológica.']];return `<div class="aesthetic-points">${points.map(([title,text])=>`<div><span>${icon('check',13)}</span><section><h4>${title}</h4><p>${text}</p></section></div>`).join('')}</div><p class="photo-case-note">${whitening?'Comparação ilustrativa com a mesma fotografia de base e ajuste localizado da cor do esmalte. Não prevê resultado clínico.':'Exemplo estético de restaurações para discutir lentes e facetas. A prévia não determina espessura, material, preparo ou viabilidade clínica.'}</p>`}

function smileSVG(after=false){const whiteness=after?({BL1:'#fffef9',BL2:'#f9f5e9',A1:'#fffcf4',B1:'#fffffc',A2:'#f6ebd5',A3:'#ebd8b6'}[smile.shade]||'#fff'):'#e5d0a5';const restorative=after&&(smile.procedure||'clareamento')!=='clareamento';const factor=smile.procedure==='lentes'?.5:1;const align=restorative?smile.alignment/100*factor:0;const shape=restorative?.2+(smile.shape/100-.2)*factor:.2;return `<svg viewBox="0 0 600 380" xmlns="http://www.w3.org/2000/svg"><defs><radialGradient id="skin${after}"><stop stop-color="#f2d8c1"/><stop offset="1" stop-color="#c9a18b"/></radialGradient><linearGradient id="lip${after}" x2="0" y2="1"><stop stop-color="#b87573"/><stop offset=".5" stop-color="#d39890"/><stop offset="1" stop-color="#b97773"/></linearGradient></defs><rect width="600" height="380" fill="url(#skin${after})"/><path d="M70 180Q160 100 250 136Q300 145 350 136Q440 100 530 180Q450 282 300 285Q150 282 70 180Z" fill="url(#lip${after})"/><path d="M97 182Q190 160 300 165Q410 160 503 182Q420 255 300 251Q180 255 97 182Z" fill="#663d39"/><path d="M115 179Q300 145 485 179L470 201Q300 225 130 201Z" fill="#b97f79"/>${Array.from({length:10},(_,i)=>{const x=119+i*36.2;const central=i>=3&&i<=6;const h=central?66:51;const wobble=after?(1-align)*[5,-4,6,0,-5,4,0,5,-3,2][i]:[5,-4,6,0,-5,4,0,5,-3,2][i];return `<rect x="${x}" y="${164+Math.abs(i-4.5)*1.7+wobble}" width="${central?37:35}" height="${h}" rx="${7+shape*7}" fill="${whiteness}" stroke="#c6b89b" stroke-width="1.1" transform="rotate(${after?(1-align)*[3,-2,2,-2,1,-1,2,-3,2,-3][i]:[3,-2,2,-2,1,-1,2,-3,2,-3][i]} ${x+18} 185)"/>`}).join('')}<path d="M115 181Q300 142 485 181" fill="none" stroke="#d4948c" stroke-width="8" stroke-linecap="round"/><path d="M133 229Q300 268 468 229" fill="none" stroke="#cf9187" stroke-width="17" stroke-linecap="round"/><path d="M133 250Q300 302 467 250" fill="none" stroke="#f3c7b0" stroke-width="2" opacity=".3"/><text x="300" y="341" text-anchor="middle" fill="#896f60" font-family="Arial" font-size="11" letter-spacing="2">ILUSTRAÇÃO DEMONSTRATIVA</text></svg>`}
function smileStage(){if(smile.mode==='photo'&&!smile.photo)return `<div class="smile-before dental-atlas dental-before" role="img" aria-label="Antes: caso ilustrativo de sorriso natural"></div><div class="smile-after dental-atlas dental-after ${(smile.procedure||'clareamento')==='clareamento'?'dental-whitening':'dental-restorative'}" data-smile-shade="${smileShade()}" role="img" aria-label="Depois: prévia ilustrativa de ${esc(smileProcedure())}"></div><span class="compare-label left">Antes · ilustração</span><span class="compare-label right">Depois · ${esc(smileProcedure())}</span><div class="compare-line"><span>↔</span></div><input class="smile-range" id="compare-slider" type="range" min="1" max="99" value="${smile.compare}" aria-label="Comparar antes e depois">`;return `<div class="smile-before">${smile.photo?`<img src="${window.Veneer.reference()}" alt="Foto de referência antes da montagem">`:smileSVG(false)}</div><div class="smile-after">${smile.photo?`<img src="${window.Veneer.after()}" alt="Foto com ensaio visual localizado do sorriso" >`:smileSVG(true)}</div><span class="compare-label left">${smile.photo?'Referência enviada':'Original ilustrativo'}</span><span class="compare-label right">${smile.photo?esc(window.Veneer.status()):'Prévia demonstrativa'}</span><div class="compare-line ${smile.photo&&!window.Veneer.state().enabled?'comparison-pending':''}"><span>↔</span></div><input class="smile-range" id="compare-slider" type="range" min="1" max="99" value="${smile.compare}" aria-label="Comparar antes e depois" ${smile.photo&&!window.Veneer.state().enabled?'disabled':''}>`}
function renderSmile(){if(!db.patients.length)return heading('Cadastre seu primeiro paciente','Os registros e planejamentos ficam vinculados ao paciente.',btn('Novo paciente','new-patient','plus','primary'));return `<div class="smile-page-heading">${heading('Sorriso com IA','Visualize novas possibilidades para o sorriso e converse sobre cada etapa do tratamento com mais clareza e confiança.')}</div>`+`<div class="smile-layout">${card('Veja uma prévia do seu novo sorriso depois do tratamento','',`${smileProcedureOptions()}<div class="smile-stage ${smile.photo?'uploaded-photo-stage':smile.mode==='photo'?'photo-case-stage':''}" id="smile-stage" style="--compare:${smile.compare}%">${smileStage()}</div>${smile.photo?window.Veneer.feedback():''}<div class="photo-upload-row"><label class="upload-zone upload-below-photo">${icon('upload',23)}${smile.photo?'Trocar imagem':'Adicionar imagem do dispositivo'}<small>JPG ou PNG · Até 4 MB · Não envie fotos reais de pacientes</small><input type="file" id="smile-photo" accept="image/jpeg,image/png" hidden></label>${smile.photo?btn('Usar ilustração de exemplo','reset-photo','','ghost'):''}</div><div class="simulation-result"><div><h3 id="simulation-title">${smile.generated?'Prévia demonstrativa pronta':smile.photo?(window.Veneer.state().status==='error'?'Escolha outra foto para continuar':'Preparando seu sorriso'):'Seu planejamento começa aqui'}</h3><p>${smile.photo?esc(window.Veneer.message()):'Escolha o tratamento e a tonalidade para preparar sua apresentação.'}</p><small class="smile-reference-note">${smile.photo?'Prévia estética local: uniformiza a cor do esmalte e preserva a anatomia da foto. Não reconstrói dentes nem prevê resultado clínico.':'Ensaio visual para apresentação. Não simula preparo nem prevê resultado clínico.'}</small></div>${btn('Salvar prévia','save-simulation','download','',smile.generated?'':'disabled')}</div>`)}${card('Planejamento do sorriso','',smilePlanningPanel())}</div>${card('Planejamentos salvos','Sua galeria de demonstração',`<div class="table-wrap"><table><thead><tr><th>Paciente</th><th>Data</th><th>Tratamento</th><th>Tonalidade</th><th>Alinhamento</th><th></th></tr></thead><tbody>${db.simulations.map(s=>`<tr><td><div class="person-cell">${avatar(patient(s.patient))}<strong>${esc(patient(s.patient).name)}</strong></div></td><td>${prettyDate(s.date)}</td><td>${esc(smileProcedures[s.procedure]||'Não informado')}</td><td>${esc(s.shade)}</td><td>${s.mode==='photo'?'—':s.alignment+'%'}</td><td>${btn('Abrir prévia','open-simulation','','',`data-id="${s.id}"`)}</td></tr>`).join('')||'<tr><td colspan="6">Nenhuma prévia salva ainda.</td></tr>'}</tbody></table></div>`,'','settings-section').replace('class="card settings-section"','class="card settings-section" style="margin-top:22px"')}`}
function patientOptions(selected=''){return db.patients.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)}</option>`).join('')}
function renderTeleconsultas(){const calls=db.appointments.filter(a=>a.type==='Teleconsulta'&&a.status!=='Cancelado');return `<div class="teleconsult-page ${callState?'has-active-session':'teleconsult-directory'}">`+(callState?`<div class="teleconsult-session-toolbar"><button type="button" class="button ghost teleconsult-back" data-session-action="back" title="Sair da chamada e voltar à Agenda">${icon('arrow',16)}Voltar à Agenda</button><span>Atendimento por vídeo</span></div>`:heading('TELECONSULTA','Cuidado que ultrapassa distância',`<button type="button" class="button ghost teleconsult-back" data-route="agenda">${icon('arrow',16)}Voltar à Agenda</button>`+btn('Agendar teleconsulta','new-teleconsult','plus','primary')))+(callState?renderCall():window.TeleconsultDirectory.render(calls))+`</div>`}

function renderCall(){return window.VideoRoom.render()}
let certificate={date:dateKey(),days:'',cro:'',from:'',to:'',editing:false,needsReview:false};
const docTypes=['Receituário Odontológico','Declaração de comparecimento','Atestado Odontológico','Plano de Atendimento','Orientações e cuidados','Termo de consentimento'];
function documentText(type,p){const canonical=({'Atestado odontológico':'Atestado Odontológico','Plano de tratamento':'Plano de Atendimento','Orientações de cuidado':'Orientações e cuidados'})[type]||type;if(window.SessionNotes.types.includes(canonical)){if(canonical==='Receituário Odontológico')return 'Prescrição:\n[Preencher medicamento, apresentação, posologia, via e duração conforme avaliação do dentista]';return window.SessionNotes.template(canonical,p,certificate)}if(type==='Atestado odontológico')return `ATESTADO ODONTOLÓGICO — MODELO\n\nAtesto, para os devidos fins, que ${p.name} necessita de afastamento de suas atividades por ${certificate.days||'[quantidade de dias]'} dia(s), a contar de ${prettyDate(certificate.date,{day:'numeric',month:'long',year:'numeric'})}, em decorrência de atendimento odontológico.\n\nProfissional: ${db.settings.doctor}\nCRO/UF: ${certificate.cro||'[preencher registro profissional]'}\n\nModelo para revisão e assinatura do cirurgião-dentista responsável, após avaliação. A duração do afastamento deve ser definida pelo profissional. Sem assinatura, este modelo não comprova atendimento nem constitui atestado emitido.`;if(type==='Plano de tratamento')return `Paciente: ${p.name}\n\nPlanejamento proposto para apresentação:\n\n${p.treatments.map((t,i)=>`${i+1}. ${t.name} — ${money(t.value)} (${t.status})`).join('\n')||'Nenhum procedimento adicionado ao plano.'}\n\nTotal demonstrativo: ${money(p.treatments.reduce((s,t)=>s+t.value,0))}.\n\nOs valores e procedimentos são fictícios. Este documento não constitui uma proposta clínica real.`;if(type==='Termo de consentimento')return `Eu, ${p.name}, declaro que recebi explicações sobre as etapas de um planejamento odontológico fictício, incluindo alternativas e esclarecimento de dúvidas.\n\nEste texto é um exemplo de interface. Não substitui um termo elaborado para um tratamento real e não registra consentimento válido.\n\nLocal e data: São Paulo, ${prettyDate(dateKey(),{day:'numeric',month:'long',year:'numeric'})}.`;if(type==='Orientações de cuidado')return `Paciente: ${p.name}\n\nExemplo de material educativo para apresentação da plataforma.\n\n• Mantenha uma rotina de higiene bucal.\n• Siga as orientações individualizadas do seu profissional.\n• Compareça às consultas de acompanhamento.\n• Em caso de desconforto ou dúvida, procure seu dentista.\n\nEstas orientações são genéricas e demonstrativas. Não há avaliação ou prescrição individual neste sistema.`;return `Declaramos, exclusivamente para fins de demonstração da plataforma, que ${p.name} possui um atendimento fictício registrado em ${prettyDate(dateKey(),{day:'numeric',month:'long',year:'numeric'})}.\n\nEste documento não comprova comparecimento real e não possui validade clínica, trabalhista ou jurídica.`}
function paper(type,p,text){return window.DocumentActions.markup({type,patient:p.id,patientName:p.name,patientCpf:p.cpf||'',professional:db.settings.doctor,cro:certificate.cro,date:certificate.date||dateKey(),text:text??documentText(type,p)},'document-paper')}
function renderDocuments(){if(!certificate.editing)certificate.date=dateKey();if(!db.patients.length)return heading('Cadastre seu primeiro paciente','Os registros e planejamentos ficam vinculados ao paciente.',btn('Novo paciente','new-patient','plus','primary'));const p=patient(documentPatient),isCertificate=documentType==='Atestado Odontológico',isPrescription=documentType==='Receituário Odontológico',isAttendance=documentType==='Declaração de comparecimento';const input=(label,id,type,value,extra='')=>`<label class="field"><span>${label}</span><input id="${id}" type="${type}" value="${esc(value||'')}" ${extra}></label>`;const fields=(isCertificate||isAttendance?input(isCertificate?'Início do afastamento':'Data do atendimento','certificate-date','date',certificate.date):'')+(isCertificate?input('Dias definidos pelo profissional','certificate-days','number',certificate.days,'min="1" max="365" step="1"'):'')+(isCertificate||isPrescription?input('CRO/UF do profissional','certificate-cro','text',certificate.cro,'maxlength="60"'):'')+(isAttendance?input('Início do atendimento','certificate-from','time',certificate.from)+input('Fim do atendimento','certificate-to','time',certificate.to):'');return heading('Documentos que acompanham o cuidado.','Prepare, revise e organize os documentos do paciente.',`${btn('Atestado','new-certificate','file')}${btn('Novo documento','new-document','plus','primary')}`)+`<div class="two-columns"><section>${paper(documentType,p)}</section>${card('Preparar documento','Escolha o modelo e o paciente.',`<div class="card-body"><label class="field"><span>Modelo</span><select id="document-type">${docTypes.map(t=>`<option ${t===documentType?'selected':''}>${t}</option>`).join('')}</select></label><label class="field" style="margin-top:20px"><span>Paciente</span><select id="document-patient">${patientOptions(documentPatient)}</select></label>${fields?`<div class="form-grid certificate-fields">${fields}</div>`:''}<div id="document-review" role="alert" ${certificate.needsReview?'':'hidden'}><p>Os dados foram alterados após a edição do texto. Atualize o modelo ou confira o conteúdo antes de salvar ou imprimir.</p><div class="session-record-actions">${btn('Atualizar texto pelo modelo','document-use-template')}${btn('Conferi o texto com os dados','document-review-text')}</div></div><label class="field" style="margin-top:20px"><span>Conteúdo do documento</span><textarea id="document-text" rows="9" maxlength="20000">${esc(documentText(documentType,p))}</textarea><small>Revise o conteúdo antes de salvar. Prescrição e afastamento devem ser definidos pelo dentista.</small></label><div class="session-record-actions" style="margin-top:20px">${btn('Salvar documento','save-document','file','primary')}${btn('Imprimir / PDF','print-document','print')}</div><p class="clinical-local">Modelos locais para revisão e assinatura do profissional, sem assinatura digital.</p></div>`)}</div><div style="margin-top:22px">${card('Documentos salvos','Vinculados ao paciente e disponíveis no prontuário.',`<div class="table-wrap"><table><thead><tr><th>Documento</th><th>Paciente</th><th>Data</th><th>Status</th><th>Ações</th></tr></thead><tbody>${db.documents.map(d=>`<tr><td><strong>${esc(d.type)}</strong>${d.sessionId?'<small class="document-session-label">Teleconsulta</small>':''}</td><td>${esc(d.patientName||patient(d.patient).name)}</td><td>${prettyDate(d.date)}${d.time?' · '+esc(d.time):''}</td><td>${badge(d.status)}</td><td><div class="session-record-actions">${DocumentActions.action('Visualizar','view',d.id)}${DocumentActions.action('Baixar PDF','pdf',d.id)}${DocumentActions.action('Enviar ao cliente','share',d.id)}</div></td></tr>`).join('')||'<tr><td colspan="5">Nenhum documento salvo.</td></tr>'}</tbody></table></div>`)}</div>`}
function financeStats(){const income=db.transactions.filter(t=>t.kind==='Receita'&&t.status==='Recebido').reduce((s,t)=>s+t.value,0);const expense=db.transactions.filter(t=>t.kind==='Despesa'&&t.status==='Pago').reduce((s,t)=>s+t.value,0);const pending=db.transactions.filter(t=>t.kind==='Receita'&&t.status==='Pendente').reduce((s,t)=>s+t.value,0);return {income,expense,pending,balance:income-expense}}
function transactionRows(){const list=db.transactions.filter(t=>financeFilter==='Todos'||(financeFilter==='Receitas'?t.kind==='Receita':financeFilter==='Despesas'?t.kind==='Despesa':t.status==='Pendente')).sort((a,b)=>b.date.localeCompare(a.date));return list.map(t=>`<tr><td><strong style="font-weight:500">${esc(t.description)}</strong><div class="muted" style="font-size:8px;margin-top:5px">${t.patient?esc(patient(t.patient).name):'Despesa da clínica'}</div></td><td>${prettyDate(t.date)}</td><td>${esc(t.method)}</td><td>${badge(t.status)}</td><td class="transaction-amount ${t.kind==='Despesa'?'expense':''}">${t.kind==='Despesa'?'−':''}${money(t.value)}</td><td>${t.status==='Pendente'?btn('Receber','receive-payment','check','',`data-id="${t.id}"`):`<span class="muted">${icon('check',14)}</span>`}</td></tr>`).join('')||'<tr><td colspan="6">Nenhum lançamento com este filtro.</td></tr>'}
function renderFinance(){const s=financeStats();return heading('Saúde financeira, com clareza.','Acompanhe entradas, despesas e recebimentos da demonstração.',`${btn('Exportar CSV','export-finance','download')}${btn('Novo lançamento','new-transaction','plus','primary')}`)+`<div class="kpi-grid">${kpi('Recebido',money(s.income),'wallet','receitas confirmadas')}${kpi('Despesas pagas',money(s.expense),'money','custos da clínica')}${kpi('Saldo demonstrativo',money(s.balance),'chart','recebido menos despesas')}${kpi('A receber',money(s.pending),'clock','pagamentos pendentes')}</div><div class="finance-chart-section">${card('Movimento da clínica','Visão do seu cuidado ao longo do tempo',`<div class="card-body" id="activity-chart">${activityChart()}</div>`,`<div class="segmented"><button data-action="chart-period" data-value="Semana" class="${chartPeriod==='Semana'?'active':''}">Semana</button><button data-action="chart-period" data-value="Mês" class="${chartPeriod==='Mês'?'active':''}">Mês</button></div>`)}</div>${card('Movimentações','Valores fictícios para apresentação',`<div class="table-wrap"><table><thead><tr><th>Descrição</th><th>Data</th><th>Forma de pagamento</th><th>Status</th><th>Valor</th><th></th></tr></thead><tbody id="finance-rows">${transactionRows()}</tbody></table></div>`,`<select id="finance-filter" style="width:135px" aria-label="Filtrar movimentações">${['Todos','Receitas','Despesas','Pendentes'].map(s=>`<option ${financeFilter===s?'selected':''}>${s}</option>`).join('')}</select>`)}<div class="notice" style="margin-top:20px">${icon('info',16)}Nenhum pagamento é processado. Os lançamentos são registros locais para demonstração.</div>`}
function renderReports(){const completed=db.appointments.filter(a=>a.status==='Concluído').length;return heading('Dados que ajudam a cuidar melhor.','Indicadores da demonstração e relatórios prontos para exportar.',btn('Exportar resumo','export-summary','download','primary'))+`<div class="kpi-grid">${kpi('Pacientes ativos',db.patients.filter(p=>p.status==='Ativo').length,'users','dos '+db.patients.length+' cadastrados')}${kpi('Atendimentos concluídos',completed,'check','na base de exemplo')}${kpi('Sorrisos planejados',db.simulations.length,'sparkles','prévias de demonstração')}${kpi('Planos cadastrados',db.patients.reduce((s,p)=>s+p.treatments.length,0),'record','procedimentos de exemplo')}</div><div class="report-status-section">${card('Status dos agendamentos','Distribuição dos dados da demonstração',`<div class="card-body">${statusDonut()}</div>`)}</div><div class="module-grid" style="margin-top:22px">${[['Pacientes','Lista completa de pacientes fictícios e contatos.','users','export-patients'],['Agenda','Todos os agendamentos, datas e status.','calendar','export-appointments']].map(([t,d,i,a])=>`<section class="report-box"><span class="kpi-icon">${icon(i,18)}</span><div><h3>${t}</h3><p>${d}</p>${btn('Baixar CSV',a,'download')}</div></section>`).join('')}</div>`}
function statusDonut(){const statuses=['Confirmado','Concluído','Pendente','Cancelado'];const counts=statuses.map(s=>db.appointments.filter(a=>a.status===s).length),total=Math.max(1,counts.reduce((s,c)=>s+c,0));let accum=0;const stops=counts.map((c,i)=>{const a=accum;accum+=c/total*100;return `${['#426c48','#a8bd82','#dfe8cc','#edf2e5'][i]} ${a}% ${accum}%`}).join(',');return `<div class="chart-donut"><div class="donut" style="background:conic-gradient(${stops})"><strong>${db.appointments.length}</strong></div><div class="donut-legend">${statuses.map((s,i)=>`<span><i></i>${s} <strong>${counts[i]}</strong></span>`).join('')}</div></div>`}
function renderSettings(){const s=db.settings;return heading('Dados cadastrais da clínica','')+`<div class="two-columns"><div>${card('Perfil da clínica','Estas informações aparecem nos documentos e na navegação.',`<form id="settings-form" class="card-body"><div class="form-grid"><label class="field full"><span>Nome da clínica</span><input name="clinic" required maxlength="60" value="${esc(s.clinic)}"></label><label class="field"><span>Profissional responsável</span><input name="doctor" required maxlength="60" value="${esc(s.doctor)}"></label><label class="field"><span>Especialidade</span><input name="specialty" maxlength="60" value="${esc(s.specialty)}"></label><label class="field"><span>Telefone</span><input name="phone" maxlength="25" value="${esc(s.phone)}"></label><label class="field"><span>E-mail</span><input name="email" type="email" maxlength="100" value="${esc(s.email)}"></label><label class="field full"><span>Endereço</span><input name="address" maxlength="150" value="${esc(s.address)}"></label></div><button class="button primary" style="margin-top:24px" type="submit">${icon('check',14)}Salvar alterações</button></form>`)}</div><div>${card('Preferências','Ajustes simulados da plataforma.',`<div class="card-body"><div class="setting-row"><div><h3>Lembretes de consulta</h3><p>Simula o envio de lembretes, sem enviar mensagens.</p></div><button class="toggle ${s.reminders?'on':''}" data-action="toggle-setting" data-key="reminders" role="switch" aria-checked="${s.reminders}" aria-label="Lembretes de consulta"></button></div><div class="setting-row"><div><h3>Notificações no painel</h3><p>Ative os avisos locais de demonstração.</p></div><button class="toggle ${s.notifications?'on':''}" data-action="toggle-setting" data-key="notifications" role="switch" aria-checked="${s.notifications}" aria-label="Notificações"></button></div></div>`)}${card('Sua conta e seus dados','Dados da clínica, salvos no Supabase.',`<div class="card-body"><p class="muted" style="font-size:14px;line-height:1.8">Entre com a mesma conta para acessar seus dados em outro dispositivo.</p><div class="cloud-settings-actions"><button type="button" class="button" data-cloud="import-local">Importar dados deste navegador</button><button class="button" data-session-action="backup">Baixar cópia dos dados</button><button type="button" class="button ghost" data-cloud="logout">Sair</button></div></div>`)}</div></div>`}
function renderMore(){const entries=[['configuracoes','settings','Configurações','Dados da clínica, preferências e sua conta.'],['financeiro','wallet','Financeiro','Receitas, despesas e valores a receber.'],['relatorios','chart','Relatórios','Indicadores e exportação dos registros.'],['tour','sparkles','Conheça a plataforma','Um tour pelos recursos do Evoluna.']];return heading('Mais','Acesse as configurações e os demais recursos da plataforma.')+`<div class="module-grid">${entries.map(([id,i,title,description])=>`<section class="report-box"><span class="kpi-icon">${icon(i,18)}</span><div><h3>${title}</h3><p>${description}</p>${id==='tour'?btn('Iniciar tour','tour','arrow'):`<button type="button" class="button" data-route="${id}">Abrir ${icon('arrow',13)}</button>`}</div></section>`).join('')}</div>`}
function moreSection(content){return `<div style="margin-bottom:18px"><button type="button" class="button ghost" data-route="mais">${icon('chevron',13)}Voltar para Mais</button></div>`+content}
const renderers={inicio:renderHome,pacientes:renderPatients,agenda:renderAgenda,prontuarios:renderRecords,prontuario:()=>window.ClinicalRecord.render(),paciente:renderPatient,sorriso:renderSmile,teleconsultas:renderTeleconsultas,documentos:renderDocuments,financeiro:()=>moreSection(renderFinance()),relatorios:()=>moreSection(renderReports()),configuracoes:()=>moreSection(renderSettings()),mais:renderMore};
function render(){if(!window.EvolunaCloud?.ready)return;if(callState&&route==='teleconsultas'&&$('#live-stage')&&$('#session-notes')){renderNav();window.SessionNotes.refresh();return}if(window.VideoRoom)window.VideoRoom.cleanup();renderNav();$('#content').innerHTML=(renderers[route]||renderHome)();window.SmileWhitening.mount();if(callState&&route==='teleconsultas')updateTimer();document.title=`${route==='paciente'?'Perfil do paciente':route==='prontuario'?'Prontuário':route==='prontuarios'?'Pacientes':navItems.find(n=>n[0]===route)?.[2]||'Visão geral'} · Evoluna Odonto · Sorriso com IA`}
function navigate(r){let base=r.split('?')[0];if(!renderers[base]){r='inicio';base=r}if(location.hash==='#'+r){route=base;render()}else location.hash=r;$('#sidebar').classList.remove('open')}
window.addEventListener('hashchange',()=>{$('#sidebar').classList.remove('open');route=location.hash.slice(1).split('?')[0]||'inicio';if(!renderers[route])route='inicio';render();window.scrollTo({top:0,behavior:'instant'})});
function openPatient(id,tab='visao'){selectedPatient=id;patientTab=tab;navigate('paciente')}
function openModal(title,body,actions='',large=false){$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${large?'large':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Fechar janela">${icon('close',18)}</button></div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}</section></div>`;const modalBody=$('.modal-body');setTimeout(()=>{if(!modalBody?.isConnected)return;const el=$('input:not([type=hidden]),select,textarea,button',modalBody);if(el)el.focus()},70)}
function closeModal(){$('#modal-root').innerHTML=''}
function field(label,name,value='',type='text',required=false,full=false,extra=''){return `<label class="field ${full?'full':''}"><span>${label}${required?' *':''}</span><input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`}
function patientModal(id){const p=id?patient(id):{};openModal(id?'Editar paciente':'Um novo sorriso na clínica',`<form id="patient-form" data-id="${id||''}"><div class="form-grid">${field('Nome completo','name',p.name,'text',true,true,'maxlength="80"')}${field('CPF (opcional)','cpf',p.cpf||'','text',false,true,'maxlength="14" inputmode="numeric" placeholder="000.000.000-00"')}${field('Data de nascimento','birth',p.birth||'1995-01-01','date',true,false,`max="${dateKey()}" min="1900-01-01"`)}<label class="field"><span>Status</span><select name="status"><option ${p.status==='Ativo'?'selected':''}>Ativo</option><option ${p.status==='Inativo'?'selected':''}>Inativo</option></select></label>${field('Telefone','phone',p.phone,'tel',true,false,'maxlength="25"')}${field('E-mail','email',p.email,'email',true,false,'maxlength="100"')}${field('Procedimento principal','procedure',p.procedure||'Avaliação inicial','text',true,false,'maxlength="80"')}${field('Plano','plan',p.plan||'Particular','text',false,false,'maxlength="60"')}${field('Alergias e atenção','allergies',p.allergies||'Sem alergias relatadas','text',false,true,'maxlength="200"')}<label class="field full"><span>Observações</span><textarea name="notes" rows="3" maxlength="1000">${esc(p.notes||'')}</textarea></label></div><p style="font-size:9px">Confira os dados do paciente antes de salvar.</p></form>`,`${btn('Cancelar','close-modal')}${`<button class="button primary" type="submit" form="patient-form">${icon('check',14)}${id?'Salvar alterações':'Cadastrar paciente'}</button>`}`)}
function appointmentModal(defaultPatient,type='Presencial'){if(!db.patients.length){patientModal();toast('Cadastre um paciente antes de agendar.');return;}openModal(type==='Teleconsulta'?'Agendar teleconsulta':'Novo agendamento',`<form id="appointment-form"><div class="form-grid"><label class="field full"><span>Paciente *</span><select name="patient">${patientOptions(defaultPatient||db.patients[0].id)}</select></label>${field('Data','date',selectedDate,'date',true)}${field('Horário','time','09:00','time',true)}<label class="field"><span>Duração</span><select name="duration"><option value="30">30 minutos</option><option value="45">45 minutos</option><option value="60">60 minutos</option></select></label><label class="field"><span>Modalidade</span><select name="type"><option ${type==='Presencial'?'selected':''}>Presencial</option><option ${type==='Teleconsulta'?'selected':''}>Teleconsulta</option></select></label>${field('Procedimento','procedure',type==='Teleconsulta'?'Acompanhamento online':'Avaliação de rotina','text',true,true,'maxlength="100"')}<label class="field"><span>Profissional</span><select name="professional"><option>${esc(db.settings.doctor)}</option><option>Dr. André Lima</option></select></label><label class="field"><span>Status</span><select name="status"><option>Confirmado</option><option>Pendente</option></select></label></div><p id="appointment-error" class="muted" role="alert"></p></form>`,`${btn('Cancelar','close-modal')}<button class="button primary" type="submit" form="appointment-form">${icon('check',14)}Salvar agendamento</button>`)}
function appointmentDetail(id){const a=db.appointments.find(a=>a.id===id),p=patient(a.patient);openModal('Detalhes do atendimento',`<div class="person-cell" style="margin-bottom:25px">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${esc(a.procedure)}</small></span></div><div class="detail-grid">${[['Data',prettyDate(a.date,{day:'numeric',month:'long',year:'numeric'})],['Horário',`${a.time} · ${a.duration} min`],['Profissional',a.professional],['Modalidade',a.type]].map(([l,v])=>`<div class="detail-field"><small>${l}</small><span>${esc(v)}</span></div>`).join('')}</div><div style="margin-top:25px">${badge(a.status)}</div>`,`${a.status!=='Cancelado'&&a.status!=='Concluído'?btn('Cancelar consulta','cancel-appointment','','danger',`data-id="${id}"`):''}${a.status==='Pendente'?btn('Confirmar','confirm-appointment','check','',`data-id="${id}"`):''}${a.status!=='Cancelado'&&a.status!=='Concluído'?btn('Concluir atendimento','complete-appointment','check','primary',`data-id="${id}"`):btn('Fechar','close-modal')}`)}
function noteModal(id){openModal('Registrar evolução',`<form id="note-form" data-id="${id}"><div class="form-grid">${field('Título do registro','title','Consulta de acompanhamento','text',true,true,'maxlength="100"')}${field('Data','date',dateKey(),'date',true,true)}<label class="field full"><span>Evolução demonstrativa *</span><textarea name="text" rows="6" required maxlength="4000" placeholder="Registre as observações fictícias do atendimento..."></textarea></label></div></form>`,`${btn('Cancelar','close-modal')}<button class="button primary" type="submit" form="note-form">Salvar evolução</button>`)}
function treatmentModal(id){openModal('Adicionar procedimento ao plano',`<form id="treatment-form" data-id="${id}"><div class="form-grid">${field('Procedimento','name','','text',true,true,'maxlength="100"')}${field('Valor demonstrativo (R$)','value','350','number',true,false,'min="0" max="999999" step="0.01"')}<label class="field"><span>Status</span><select name="status"><option>Planejado</option><option>Em andamento</option><option>Concluído</option></select></label></div></form>`,`${btn('Cancelar','close-modal')}<button class="button primary" type="submit" form="treatment-form">Adicionar procedimento</button>`)}
function transactionModal(){openModal('Novo lançamento',`<form id="transaction-form"><div class="form-grid">${field('Descrição','description','','text',true,true,'maxlength="100"')}<label class="field"><span>Tipo</span><select name="kind"><option>Receita</option><option>Despesa</option></select></label>${field('Valor (R$)','value','350','number',true,false,'min="0.01" max="9999999" step="0.01"')}${field('Data','date',dateKey(),'date',true)}<label class="field"><span>Forma de pagamento</span><select name="method"><option>Pix</option><option>Cartão</option><option>Dinheiro</option><option>Transferência</option></select></label><label class="field"><span>Paciente (opcional)</span><select name="patient"><option value="">Sem vínculo</option>${patientOptions('none')}</select></label><label class="field"><span>Situação</span><select name="situation"><option value="paid">Já recebido / pago</option><option value="pending">Pendente</option></select></label></div><p style="font-size:9px">Registro de demonstração. Nenhuma cobrança será realizada.</p></form>`,`${btn('Cancelar','close-modal')}<button class="button primary" type="submit" form="transaction-form">Salvar lançamento</button>`)}
function searchModal(){window.DrHelp.open()}
function patientLookupResults(query='') {
  const normal=v=>String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const q=normal(query.trim());
  const list=db.patients.filter(p=>normal(`${p.name} ${p.email} ${p.phone} ${p.cpf||''}`).includes(q)||(q.replace(/\D/g,'').length>=3&&`${p.phone} ${p.cpf||''}`.replace(/\D/g,'').includes(q.replace(/\D/g,''))));
  return list.map(p=>`<button class="search-result" data-action="patient" data-id="${p.id}">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${esc(p.phone)} · ${esc(p.email)}</small></span>${icon('arrow',14)}</button>`).join('')||'<div class="empty"><h3>Nenhum paciente encontrado.</h3><p>Busque por nome, telefone ou e-mail.</p></div>';
}
function patientLookupModal(){openModal('Buscar pacientes',`<div class="input-search" style="max-width:100%">${icon('search',16)}<input id="patient-lookup-input" placeholder="Nome, telefone ou e-mail" aria-label="Nome, telefone ou e-mail do paciente"></div><div id="patient-lookup-results" class="search-results">${patientLookupResults()}</div>`)}

function notifications(){openModal('O cuidado está em movimento',db.activity.map(a=>`<div class="activity-item"><span class="kpi-icon">${icon(a.icon,15)}</span><div><p>${esc(a.text)}</p><small>${prettyDate(a.date)} · Atividade demonstrativa</small></div></div>`).join('')||'<p>Nenhuma atividade ainda.</p>')}
function updateTimer(){if(!callState?.started)return;const sec=Math.floor((Date.now()-callState.started)/1000);const el=$('#call-timer');if(el)el.textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`}
function download(content,name,type='text/csv;charset=utf-8'){const blob=new Blob([content],{type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),2000)}
function csvCell(v){const raw=String(v??'');return '"'+(/^[=+\-@\t\r]/.test(raw)?"'"+raw:raw).replace(/"/g,'""')+'"'}
function exportCSV(kind){let headers,rows;if(kind==='patients'){headers=['Nome','E-mail fictício','Telefone fictício','Status','Procedimento'];rows=db.patients.map(p=>[p.name,p.email,p.phone,p.status,p.procedure])}else if(kind==='appointments'){headers=['Data','Horário','Paciente','Procedimento','Profissional','Modalidade','Status'];rows=db.appointments.map(a=>[a.date,a.time,patient(a.patient).name,a.procedure,a.professional,a.type,a.status])}else if(kind==='summary'){const s=financeStats();headers=['Indicador','Valor demonstrativo'];rows=[['Pacientes',db.patients.length],['Agendamentos',db.appointments.length],['Simulações',db.simulations.length]]}else{headers=['Descrição','Tipo','Paciente','Data','Valor (R$)','Status','Forma'];rows=db.transactions.map(t=>[t.description,t.kind,t.patient?patient(t.patient).name:'',t.date,t.value,t.status,t.method])}download('\ufeff'+[headers,...rows].map(r=>r.map(csvCell).join(';')).join('\r\n'),`sorriso-demo-${kind}-${dateKey()}.csv`);toast('Relatório demonstrativo exportado.')}
const tours=[{route:'inicio',title:'Sua clínica em um só olhar.',text:'Comece pelos indicadores, veja a agenda do dia e acompanhe os pacientes. Todos os dados desta apresentação são fictícios.'},{route:'pacientes',title:'Cada sorriso tem uma história.',text:'Abra o perfil de Mariana Oliveira, explore as evoluções, marque o odontograma e adicione procedimentos ao plano. Você também pode cadastrar novos pacientes fictícios.'},{route:'agenda',title:'Um dia de cuidado bem organizado.',text:'Navegue entre as datas, agende uma consulta, confirme ou conclua os atendimentos. Os dados ficam salvos neste navegador.'},{route:'sorriso',title:'Uma conversa visual sobre possibilidades.',text:'Ajuste a tonalidade e o alinhamento da ilustração. Arraste a divisória para comparar e salve uma prévia. O processamento de IA é simulado.'},{route:'teleconsultas',title:'Presença que vai além do consultório.',text:'Prepare uma chamada real no Jitsi, permita câmera e microfone e compartilhe o link exclusivo. O organizador precisa entrar no serviço externo.'},{route:'documentos',title:'Do planejamento à organização.',text:'Gere documentos de exemplo, imprima em PDF, acompanhe o financeiro e exporte relatórios. Tudo pronto para você apresentar a jornada completa.'}];
function showTour(){const t=tours[tourStep];navigate(t.route);$('#tour-root').innerHTML=`<div class="tour-overlay"><section class="tour-panel" role="dialog" aria-modal="true" aria-label="Tour de apresentação"><div style="display:flex;justify-content:space-between;align-items:center"><span class="eyebrow">TOUR DA PLATAFORMA · ${tourStep+1} DE ${tours.length}</span><button class="icon-button" data-action="end-tour" aria-label="Fechar tour">${icon('close',17)}</button></div><h2>${t.title}</h2><p>${t.text}</p><div class="tour-actions"><div class="tour-dots">${tours.map((t,i)=>`<i class="${i===tourStep?'active':''}"></i>`).join('')}</div><div style="display:flex;gap:8px">${tourStep>0?btn('Voltar','prev-tour','','ghost'):''}${btn(tourStep===tours.length-1?'Explorar plataforma':'Próxima etapa','next-tour','arrow','primary')}</div></div></section></div>`}
document.addEventListener('click',async e=>{if(e.target.closest('#navigation a[href^="#"]'))$('#sidebar').classList.remove('open');const routeEl=e.target.closest('[data-route]');if(routeEl){navigate(routeEl.dataset.route);return}const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;switch(a){
case'menu':$('#sidebar').classList.toggle('open');break;
case'close-modal':closeModal();break;
case'new-patient':patientModal();break;
case'edit-patient':patientModal(id);break;
case'patient':closeModal();openPatient(id);break;
case'open-record':window.ClinicalRecord.open(id);break;
case'patient-tab':patientTab=el.dataset.tab;render();break;
case'patient-view':patientView=el.dataset.value;render();break;
case'new-appointment':appointmentModal(el.dataset.patient);break;
case'new-teleconsult':appointmentModal(null,'Teleconsulta');break;
case'appointment-detail':appointmentDetail(id);break;
case'select-day':selectedDate=el.dataset.date;render();break;
case'prev-day':selectedDate=addDay(selectedDate,-1);render();break;
case'next-day':selectedDate=addDay(selectedDate,1);render();break;
case'today':selectedDate=dateKey();render();break;
case'confirm-appointment':case'cancel-appointment':case'complete-appointment':{const ap=db.appointments.find(x=>x.id===id);ap.status=a==='confirm-appointment'?'Confirmado':a==='cancel-appointment'?'Cancelado':'Concluído';if(ap.status==='Concluído'){const p=patient(ap.patient);p.last=ap.date;p.history.unshift({date:ap.date,title:ap.procedure,text:'Atendimento marcado como concluído na agenda.'})}if(!await activity(`Atendimento de ${patient(ap.patient).name}: ${ap.status.toLowerCase()}.`,'calendar'))return;closeModal();render();toast('Agendamento atualizado.');break}
case'new-note':noteModal(id);break;
case'new-treatment':treatmentModal(id);break;
case'tooth':{const p=patient(selectedPatient),n=el.dataset.tooth;p.teeth[n]=p.teeth[n]==='marked'?'treatment':p.teeth[n]==='treatment'?'':'marked';if(!await save())return;el.className='tooth '+p.teeth[n];el.setAttribute('aria-label',`Dente ${n}: ${p.teeth[n]==='marked'?'acompanhamento':p.teeth[n]==='treatment'?'tratamento':'íntegro'}`);toast(`Dente ${n}: ${p.teeth[n]==='marked'?'acompanhamento':p.teeth[n]==='treatment'?'tratamento':'íntegro'}.`);break}
case'chart-period':chartPeriod=el.dataset.value;render();break;
case'search':searchModal();break;
case'patient-search':patientLookupModal();break;
case'notifications':notifications();break;
case'ready-veneers':smile.photo=null;smile.mode='photo';smile.generated=true;smile.compare=50;render();toast('Caso ilustrativo de '+smileProcedure()+' pronto para apresentação.');break;
case'smile-mode':smile.mode=el.dataset.value;smile.generated=false;render();break;
case'present-smile':{const stage=smileStage().replace('id="compare-slider"','id="presentation-compare"');openModal('Antes e depois · apresentação do sorriso',`<div class="smile-stage ${smile.photo?'uploaded-photo-stage':smile.mode==='photo'?'photo-case-stage':''} presentation-stage" style="--compare:${smile.compare}%">${stage}</div><p class="photo-case-note">Comparação ilustrativa para conversar sobre estética e expectativas. Não documenta resultado clínico nem prevê tratamento individual.</p>`,'',true);window.SmileWhitening.mount();break;}
case'smile-select-patient':if(!db.patients.some(p=>p.id===id))break;smile.patient=id;render();$('#smile-patient-search')?.focus();$('#smile-patient-results').hidden=true;$('#smile-patient-search').setAttribute('aria-expanded','false');toast('Paciente selecionado: '+patient(id).name);break;
case'shade':smile.shade=el.dataset.value;smile.generated=false;if(smile.photo){window.Veneer.apply();break}render();break;
case'reset-photo':window.Veneer.cancel();smile.photo=null;delete smile.veneers;smile.generated=false;render();break;
case'generate-smile':{if(smile.photo){window.Veneer.apply();break}el.disabled=true;el.textContent='Preparando a demonstração...';$('#simulation-progress').innerHTML='<div class="loading-bar"><span></span></div>';setTimeout(()=>{smile.generated=true;if(route==='sorriso'){render();toast('Prévia ilustrativa pronta. Arraste para comparar.')}},1800);break}
case'save-simulation':{if(!smile.generated)return;if(!db.patients.some(p=>p.id===smile.patient))smile.patient=db.patients[0]?.id;const s={id:uid('s'),patient:smile.patient,date:dateKey(),procedure:smile.procedure||'clareamento',mode:smile.mode,photo:smile.photo,veneers:smile.veneers?window.Veneer.snapshot():null,shade:smileShade(),alignment:smile.alignment,shape:smile.shape};db.simulations.unshift(s);if(!await activity(`Prévia ilustrativa de ${patient(s.patient).name} salva.`,'sparkles'))return;render();toast('Prévia salva na galeria de demonstração.');break}
case'open-simulation':{window.Veneer.cancel();const s=db.simulations.find(x=>x.id===id);smile={...smile,...s,procedure:s.procedure||'clareamento',generated:true,photo:s.photo||null};if(smile.photo&&smile.veneers?.maskVersion!==14){window.Veneer.apply()}else render();toast('Planejamento carregado no estúdio.');window.scrollTo({top:0,behavior:'smooth'});break}
case'start-call':{const ap=db.appointments.find(x=>x.id===id);if(!ap)return;const session=await window.SessionNotes.start(ap);if(!session)return;callState={patient:ap.patient,appointment:ap.id,session:session.id,room:window.VideoRoom.roomFor(ap),started:null,connected:false,notes:''};navigate('teleconsultas');break}
case'save-call-note':await window.SessionNotes.saveDraft();break;
case'end-call':window.SessionNotes.requestFinish();break;
case'confirm-end-call':await window.SessionNotes.finish();break;
case'new-certificate':documentType='Atestado Odontológico';navigate('documentos');render();break;
case'new-document':documentType='Declaração de comparecimento';navigate('documentos');toast('Selecione o paciente e edite o modelo ao lado.');break;
case'save-document':{if(!db.patients.some(p=>p.id===documentPatient))documentPatient=db.patients[0]?.id;const text=$('#document-text').value.trim();const d=await window.SessionNotes.saveStandalone(documentType,documentPatient,text,{...certificate});if(d){render();window.DocumentActions.view(d);toast('Documento salvo e vinculado ao paciente.')}break}
case'document-use-template':{const textarea=$('#document-text');textarea.value=documentText(documentType,patient(documentPatient));delete textarea.dataset.userEdited;certificate.needsReview=false;$('#document-review').hidden=true;$('#document-paper').outerHTML=paper(documentType,patient(documentPatient),textarea.value);break}
case'document-review-text':certificate.needsReview=false;$('#document-review').hidden=true;toast('Revisão do texto confirmada.');break;
case'print-document':{if(certificate.needsReview){toast('Confira o texto com os dados antes de imprimir.');return}const text=$('#document-text')?.value;$('#document-paper').outerHTML=paper(documentType,patient(documentPatient),text);window.print();break}
case'view-document':window.DocumentActions.view(window.DocumentActions.find(id));break;
case'download-document':{const d=window.DocumentActions.find(id);if(d)await window.DocumentActions.download([d]);break}
case'new-transaction':transactionModal();break;
case'receive-payment':{const t=db.transactions.find(x=>x.id===id);t.status=t.kind==='Receita'?'Recebido':'Pago';if(!await activity(`Lançamento atualizado: ${t.description}.`,'wallet'))return;render();toast('Pagamento marcado na demonstração. Nenhuma cobrança realizada.');break}
case'export-patients':exportCSV('patients');break;
case'export-appointments':exportCSV('appointments');break;
case'export-finance':exportCSV('finance');break;
case'export-summary':exportCSV('summary');break;
case'toggle-setting':{const key=el.dataset.key;db.settings[key]=!db.settings[key];if(!await save())return;el.classList.toggle('on',db.settings[key]);el.setAttribute('aria-checked',String(db.settings[key]));toast('Preferência de demonstração atualizada.');break}
case'reset-demo':openModal('Restaurar a demonstração?',`<p>Os cadastros e alterações feitos neste navegador serão substituídos pelos exemplos iniciais. Isso não afeta nenhum sistema real.</p>`,`${btn('Cancelar','close-modal')}${btn('Restaurar exemplos','confirm-reset','refresh','danger')}`);break;
case'confirm-reset':db=seed();if(!await save())return;callState=null;clearInterval(callTimer);smile={procedure:'clareamento',mode:'photo',patient:'p5',shade:'BL1',alignment:65,shape:50,compare:50,photo:null,generated:false};selectedDate=dateKey();selectedPatient='p1';documentPatient='p1';patientQuery='';patientStatus='Todos';closeModal();navigate('inicio');render();toast('Demonstração restaurada. Tudo pronto para apresentar.');break;
case'fullscreen':try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast('Use o modo tela cheia do seu navegador.')}break;
case'tour':tourStep=0;showTour();break;
case'next-tour':tourStep++;if(tourStep>=tours.length){$('#tour-root').innerHTML='';tourStep=-1;toast('Pronto para apresentar. Explore os módulos no menu.')}else showTour();break;
case'prev-tour':tourStep=Math.max(0,tourStep-1);showTour();break;
case'end-tour':$('#tour-root').innerHTML='';tourStep=-1;break;
}});
document.addEventListener('input',e=>{const el=e.target;switch(el.id){case'smile-patient-search':{const results=$('#smile-patient-results');results.innerHTML=smilePatientResults(el.value);results.hidden=false;el.setAttribute('aria-expanded','true');break}case'patient-lookup-input':$('#patient-lookup-results').innerHTML=patientLookupResults(el.value);break;case'patient-search':patientQuery=el.value;$('#patients-list').innerHTML=patientCards();break;case'presentation-compare':case'compare-slider':smile.compare=Number(el.value);el.closest('.smile-stage').style.setProperty('--compare',smile.compare+'%');break;case'alignment':case'shape':{smile[el.id]=Number(el.value);smile.generated=false;$('#'+el.id+'-value').textContent=el.value+'%';const stage=$('#smile-stage');stage.innerHTML=smileStage();const saveButton=$('[data-action="save-simulation"]');if(saveButton)saveButton.disabled=true;break}case'document-text':{certificate.editing=true;el.dataset.userEdited='true';const p=$('#document-paper>p');if(p)p.textContent=el.value;break}case'call-notes':if(callState)callState.notes=el.value;break}});
document.addEventListener('change',e=>{const el=e.target;if(el.name==='smile-procedure'){smile.procedure=el.value;smile.generated=false;if(smile.photo){window.Veneer.apply();return}render();return}switch(el.id){case'patient-status':patientStatus=el.value;$('#patients-list').innerHTML=patientCards();break;case'agenda-status':agendaStatus=el.value;render();break;case'finance-filter':financeFilter=el.value;$('#finance-rows').innerHTML=transactionRows();break;case'smile-patient':smile.patient=el.value;break;case'document-type':documentType=el.value;certificate.editing=false;certificate.needsReview=false;render();break;case'document-patient':documentPatient=el.value;certificate.editing=false;certificate.needsReview=false;render();break;case'smile-photo':{const f=el.files[0];if(!f)return;if(!['image/jpeg','image/png'].includes(f.type)||f.size>4*1024*1024){toast('Escolha uma imagem JPG ou PNG com até 4 MB.');return}window.Veneer.read(f);break}}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['patient-form','appointment-form','note-form','treatment-form','transaction-form','settings-form'].includes(f.id))return;e.preventDefault();const v=Object.fromEntries(new FormData(f));switch(f.id){case'patient-form':{const editing=f.dataset.id;const p=editing?patient(editing):{id:uid('p'),color:db.patients.length%4,last:dateKey(),teeth:{},history:[],treatments:[]};Object.assign(p,v);if(!editing)db.patients.unshift(p);if(!await activity(`${p.name}: cadastro ${editing?'atualizado':'criado'}.`,'users'))return;closeModal();render();toast(editing?'Cadastro atualizado.':'Paciente cadastrado.');break}case'appointment-form':{const overlapping=db.appointments.filter(a=>a.date===v.date&&a.status!=='Cancelado'&&timeMinutes(a.time)<timeMinutes(v.time)+Number(v.duration)&&timeMinutes(v.time)<timeMinutes(a.time)+Number(a.duration));if(overlapping.some(a=>a.patient===v.patient)){const message='Cliente já agendado para esta data e horário.';$('#appointment-error').textContent=message;window.alert(message);f.elements.time.focus();return}const clash=overlapping.some(a=>a.professional===v.professional);if(clash){$('#appointment-error').textContent='Este profissional já tem uma consulta nesse intervalo. Escolha outro horário.';return}db.appointments.push({...v,id:uid('a'),duration:Number(v.duration)});selectedDate=v.date;if(!await activity(`Consulta de ${patient(v.patient).name} agendada para ${prettyDate(v.date)} às ${v.time}.`,'calendar'))return;closeModal();navigate('agenda');render();toast('Agendamento salvo.');break}case'note-form':{const p=patient(f.dataset.id);p.history.unshift({title:v.title,date:v.date,text:v.text});p.last=v.date;if(!await save())return;closeModal();patientTab='evolucao';render();toast('Evolução salva no prontuário.');break}case'treatment-form':patient(f.dataset.id).treatments.push({...v,value:Number(v.value)});if(!await save())return;closeModal();render();toast('Procedimento adicionado ao plano.');break;case'transaction-form':{const {situation,...data}=v;db.transactions.unshift({...data,id:uid('f'),value:Number(v.value),status:situation==='pending'?'Pendente':v.kind==='Receita'?'Recebido':'Pago'});if(!await activity(`Lançamento demonstrativo: ${v.description}.`,'wallet'))return;closeModal();render();toast('Lançamento salvo.');break}case'settings-form':Object.assign(db.settings,v);if(!await save())return;render();toast('Informações da clínica atualizadas.');break}});
function timeMinutes(t){const[h,m]=t.split(':').map(Number);return h*60+m}
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchModal()}if(e.key==='Escape'){closeModal();$('#tour-root').innerHTML='';$('#sidebar').classList.remove('open')}if(e.key==='Tab'&&$('.modal')){const list=$$('button,a,input,select,textarea', $('.modal')).filter(el=>!el.disabled&&el.type!=='hidden');if(list.length){if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0].focus()}}}});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-overlay'))closeModal();if(innerWidth<801&&$('#sidebar').classList.contains('open')&&!e.target.closest('#sidebar')&&!e.target.closest('[data-action="menu"]'))$('#sidebar').classList.remove('open')});
route=location.hash.slice(1).split('?')[0]||'inicio';if(!renderers[route])route='inicio';
window.EvolunaApp={empty:emptyDatabase,get:()=>db,set:value=>{db=value;const kept=window.EvolunaCloud.retainPatientSelections(db.patients,{selectedPatient,documentPatient,smilePatient:smile.patient});selectedPatient=kept.selectedPatient;documentPatient=kept.documentPatient;smile.patient=kept.smilePatient;},render,stop:()=>{window.VideoRoom?.end();window.Veneer?.cancel();callState=null;smile={procedure:'clareamento',mode:'photo',patient:'',shade:'BL1',alignment:65,shape:50,compare:50,photo:null,generated:false};closeModal();}};
window.EvolunaCloud.boot();

document.addEventListener('focusin',e=>{if(e.target.id==='smile-patient-search'){const results=$('#smile-patient-results');results.innerHTML=smilePatientResults(e.target.value);results.hidden=false;e.target.setAttribute('aria-expanded','true')}});
document.addEventListener('click',e=>{if(!e.target.closest('.smile-planning-panel')){const results=$('#smile-patient-results');if(results){results.hidden=true;$('#smile-patient-search')?.setAttribute('aria-expanded','false')}}});
document.addEventListener('keydown',e=>{if(e.target.id!=='smile-patient-search')return;const results=$('#smile-patient-results');if(e.key==='Escape'){results.hidden=true;e.target.setAttribute('aria-expanded','false')}if(e.key==='ArrowDown'&&!results.hidden){e.preventDefault();results.querySelector('button')?.focus()}if(e.key==='Enter'&&!results.hidden){e.preventDefault();results.querySelector('button')?.click()}});

// Atualiza o dia ao retomar a aba e na virada da meia-noite, sem refazer formulários.
let displayedDay=dateKey();
function refreshCurrentDay(){const current=dateKey();if(current===displayedDay)return false;const previous=displayedDay;displayedDay=current;if(selectedDate===previous)selectedDate=current;if(window.EvolunaCloud?.ready&&['inicio','agenda'].includes(route)&&!document.querySelector('.modal')&&!document.querySelector('input:focus,textarea:focus,select:focus'))render();return true}
window.addEventListener('focus',refreshCurrentDay);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshCurrentDay()});
for(const event of ['click','submit'])document.addEventListener(event,refreshCurrentDay,true);
setInterval(refreshCurrentDay,30000);
